<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entrega de efectivo</title><style>body{font-family:system-ui;background:#f3f6fa;color:#173454;margin:0;padding:25px}main{max-width:1000px;margin:auto;background:white;padding:28px;border-radius:14px;box-shadow:0 3px 16px #1b355015}a{color:#125aa2}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #e4eaf1;text-align:left}input,select,textarea{padding:9px;border:1px solid #aabbd0;border-radius:6px}input[type=number]{width:110px}button{background:#145b9d;color:white;padding:12px 18px;border:0;border-radius:6px;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}.fila{display:flex;justify-content:space-between;align-items:center;padding:5px;border-bottom:1px solid #edf0f5}.error{color:#ae2929}</style></head><body><main><p><a href="{{ route($ruta.'.entregas.index') }}">Volver a entregas</a></p><h1>{{ $registro->numero_arqueo }}</h1>@if(session('success'))<p>{{ session('success') }}</p>@endif@if($errors->any())<ul class="error">@foreach($errors->all() as $e)<li>{{ $e }}</li>@endforeach</ul>@endif<p><b>Agencia:</b> {{ $registro->agencia_nombre_historico }} · <b>Ventanilla:</b> {{ $registro->ventanilla_codigo_historico }}</p><p><b>Saliente:</b> {{ $registro->receptor_nombre_historico }} · <b>Entrante:</b> {{ $registro->receptor_entrante_nombre_historico }}</p><p><b>Estado:</b> {{ $registro->estado }} · <b>Fecha:</b> {{ $registro->fecha_operativa?->format('d/m/Y') }}</p><h2>Conteo</h2><table><thead><tr><th>Tipo</th><th>Denominación</th><th>Cantidad</th><th>Subtotal</th></tr></thead><tbody>@foreach($registro->detalles as $d)<tr><td>{{ $d->tipo }}</td><td>Q {{ $d->denominacion }}</td><td>{{ $d->cantidad }}</td><td>Q {{ $d->subtotal }}</td></tr>@endforeach</tbody></table><p><b>Total arqueado:</b> Q {{ $registro->total_arqueado }} · <b>Corte:</b> Q {{ $registro->total_corte }} · <b>Diferencia:</b> Q {{ $registro->diferencia }}</p><p><b>Justificación:</b> {{ $registro->justificacion_diferencia ?: 'Sin diferencia' }}</p><p><b>Observaciones:</b> {{ $registro->observaciones ?: 'Ninguna' }}</p><h2>Firmas</h2>@foreach($registro->firmas as $f)<p>{{ $f->tipo_firma }} — {{ $f->nombres_historicos }} {{ $f->apellidos_historicos }} — {{ $f->fecha_firma?->format('d/m/Y H:i') }} — {{ ($verificaciones[$f->tipo_firma]??false)?'Integridad verificada':'No válida' }}</p>@endforeach@if($esEntrante && $registro->estado==='PENDIENTE_FIRMA_ENTRANTE' && ($verificaciones['RECEPTOR']??false))<form method="post" action="{{ route('receptor.entregas.firmar',$registro->id) }}">@csrf<p><label><input type="checkbox" name="confirmar_firma" value="1" required> Revisé el conteo y confirmo la recepción del efectivo mediante mi firma.</label></p><button type="submit">Firmar como receptor entrante</button></form>@endif@if($esCaja && $registro->estado==='PENDIENTE' && ($verificaciones['RECEPTOR']??false) && ($verificaciones['ENTRANTE']??false))<form method="post" action="{{ route($ruta.'.entregas.certificar',$registro->id) }}">@csrf<p><label><input type="checkbox" name="confirmar_certificacion" value="1" required> Revisé las dos firmas y certifico la entrega.</label></p><button type="submit">Certificar entrega</button></form>@endif</main></body></html>